// Command redirect is the redirect service (D-106, D-107): the short links of SMS and email and
// the click events.
package main

import (
	_ "embed"

	"github.com/furknozg/coldbru/internal/platform/app"
	"github.com/furknozg/coldbru/internal/redirect/boot"
	"github.com/furknozg/coldbru/internal/redirect/store"
)

// openAPISpec is generated by `make generate` (swag) and served at /openapi.json (D-057).
//
//go:embed apidocs/swagger.json
var openAPISpec []byte

// @title			Coldbru Redirect API
// @version		0.1.0
// @description	REST API of the redirect service: POST /links creates the short link of each delivery of a recipient batch (compose-internal), GET /r/{code} records the click and redirects to the stored target. Errors of POST /links are RFC 9457 application/problem+json.
// @BasePath		/
func main() {
	app.Main(app.Options{OpenAPISpec: openAPISpec, Name: "redirect", Database: true, PlatformMigrations: true, Migrations: store.Migrations(), NATS: true, Setup: boot.Setup})
}
